package pt.brunobonito.cr3paracr2;
import android.app.*; import android.content.*; import android.net.Uri; import android.os.Build; import android.provider.DocumentsContract;
import androidx.annotation.NonNull; import androidx.core.app.NotificationCompat; import androidx.work.*; import java.util.*; import java.util.concurrent.atomic.AtomicInteger;
public class RenameWorker extends Worker {
 public static final String CHANNEL="rename_progress"; public RenameWorker(@NonNull Context c,@NonNull WorkerParameters p){super(c,p);}
 @NonNull public Result doWork(){String treeS=getInputData().getString("tree"),from=getInputData().getString("from"),to=getInputData().getString("to");boolean recurse=getInputData().getBoolean("recurse",false);int policy=getInputData().getInt("policy",0);String prefix=getInputData().getString("prefix"),suffix=getInputData().getString("suffix");if(prefix==null)prefix="";if(suffix==null)suffix="";if(treeS==null||from==null||to==null)return Result.failure();Uri tree=Uri.parse(treeS);createChannel();setForegroundAsync(info(0,"A preparar ."+from.toUpperCase()+" → ."+to.toUpperCase()));List<Item> items=new ArrayList<>();scan(DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree)),recurse,from,to,policy,prefix,suffix,items);int renamed=0,ignored=0,errors=0,done=0;StringBuilder log=new StringBuilder();for(Item x:items){if(isStopped())return Result.success(out(renamed,ignored,errors,true,log.toString()));if(x.skip){ignored++;}else try{Uri changed=DocumentsContract.renameDocument(getApplicationContext().getContentResolver(),x.item,x.target);if(changed!=null){renamed++;log.append(x.dir).append('|').append(changed).append('|').append(x.old).append('|').append(x.target).append('\n');}else errors++;}catch(Exception e){errors++;}done++;int pct=items.isEmpty()?100:Math.round(done*100f/items.size());setProgressAsync(new Data.Builder().putInt("done",done).putInt("total",items.size()).putInt("pct",pct).build());setForegroundAsync(info(pct,"."+from.toUpperCase()+" → ."+to.toUpperCase()+"  •  "+done+" de "+items.size()));}return Result.success(out(renamed,ignored,errors,false,log.toString()));}
 Data out(int r,int i,int e,boolean cancelled,String log){return new Data.Builder().putInt("renamed",r).putInt("ignored",i).putInt("errors",e).putBoolean("cancelled",cancelled).putString("undo",log).build();}
 ForegroundInfo info(int p,String text){Intent intent=new Intent(getApplicationContext(),MainActivity.class);PendingIntent pi=PendingIntent.getActivity(getApplicationContext(),0,intent,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification n=new NotificationCompat.Builder(getApplicationContext(),CHANNEL).setSmallIcon(android.R.drawable.stat_sys_upload).setContentTitle("RAW Rename").setContentText(text).setProgress(100,p,false).setOngoing(p<100).setContentIntent(pi).build();return new ForegroundInfo(3001,n);}
 void createChannel(){if(Build.VERSION.SDK_INT>=26){NotificationManager nm=(NotificationManager)getApplicationContext().getSystemService(Context.NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel(CHANNEL,"Progresso de renomeação",NotificationManager.IMPORTANCE_LOW));}}
 static class Item{Uri dir,item;String old,target;boolean skip;Item(Uri d,Uri i,String o,String t,boolean s){dir=d;item=i;old=o;target=t;skip=s;}}
 void scan(Uri dir,boolean recurse,String from,String to,int policy,String prefix,String suffix,List<Item> out){Uri ch=DocumentsContract.buildChildDocumentsUriUsingTree(dir,DocumentsContract.getDocumentId(dir));String[] c={DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE};try(android.database.Cursor q=getApplicationContext().getContentResolver().query(ch,c,null,null,null)){if(q==null)return;while(q.moveToNext()){String id=q.getString(0),name=q.getString(1),mime=q.getString(2);Uri item=DocumentsContract.buildDocumentUriUsingTree(dir,id);if(DocumentsContract.Document.MIME_TYPE_DIR.equals(mime)){if(recurse)scan(item,true,from,to,policy,prefix,suffix,out);}else if(name!=null&&name.toLowerCase(Locale.ROOT).endsWith("."+from.toLowerCase(Locale.ROOT))){String oldExt=name.substring(name.length()-from.length()),target=prefix+name.substring(0,name.length()-from.length()-1)+suffix+"."+(oldExt.equals(oldExt.toUpperCase())?to.toUpperCase():to.toLowerCase());boolean exists=exists(dir,target);if(exists&&policy==1)target=unique(dir,target);out.add(new Item(dir,item,name,target,exists&&policy==0));}}}catch(Exception ignored){}}
 boolean exists(Uri d,String n){Uri ch=DocumentsContract.buildChildDocumentsUriUsingTree(d,DocumentsContract.getDocumentId(d));try(android.database.Cursor q=getApplicationContext().getContentResolver().query(ch,new String[]{DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){if(q!=null)while(q.moveToNext())if(n.equalsIgnoreCase(q.getString(0)))return true;}catch(Exception ignored){}return false;}
 String unique(Uri d,String target){int dot=target.lastIndexOf('.');String b=dot>0?target.substring(0,dot):target,e=dot>0?target.substring(dot):"";for(int n=1;n<10000;n++){String x=b+"_"+n+e;if(!exists(d,x))return x;}return b+"_novo"+e;}
}
